package main

import (
	"strings"
)

type Match struct {
	Text  string
	Score int
	Index int
}

func FuzzyMatch(text, query string, caseSensitive bool) (bool, int) {
	if !caseSensitive {
		text = strings.ToLower(text)
		query = strings.ToLower(query)
	}

	if len(query) == 0 {
		return true, 0
	}

	res := 0
	queryIdx := 0
	firstMatch := -1
	lastMatch := -1

	for i := 0; i < len(text); i++ {
		if queryIdx < len(query) && text[i] == query[queryIdx] {
			if queryIdx == 0 {
				firstMatch = i
			}
			lastMatch = i
			queryIdx++
		}
	}

	if queryIdx == len(query) {
		// Basic scoring: shorter match distance is better
		// bonus for matching at start
		score := 1000 - (lastMatch - firstMatch) - len(text)
		if firstMatch == 0 {
			score += 100
		}
		return true, score
	}

	return false, 0
}

func ExtendedMatch(text string, terms []string, caseSensitive bool) (bool, int) {
	totalScore := 0
	for _, term := range terms {
		if len(term) == 0 {
			continue
		}

		negate := false
		if strings.HasPrefix(term, "!") {
			negate = true
			term = term[1:]
		}

		if len(term) == 0 {
			continue
		}

		matched := false
		score := 0

		if strings.HasPrefix(term, "'") {
			// Exact match
			exact := term[1:]
			if caseSensitive {
				matched = strings.Contains(text, exact)
			} else {
				matched = strings.Contains(strings.ToLower(text), strings.ToLower(exact))
			}
			score = 100
		} else if strings.HasPrefix(term, "^") {
			// Prefix match
			prefix := term[1:]
			if caseSensitive {
				matched = strings.HasPrefix(text, prefix)
			} else {
				matched = strings.HasPrefix(strings.ToLower(text), strings.ToLower(prefix))
			}
			score = 100
		} else if strings.HasSuffix(term, "$") {
			// Suffix match
			suffix := term[:len(term)-1]
			if caseSensitive {
				matched = strings.HasSuffix(text, suffix)
			} else {
				matched = strings.HasSuffix(strings.ToLower(text), strings.ToLower(suffix))
			}
			score = 100
		} else {
			// Fuzzy match
			matched, score = FuzzyMatch(text, term, caseSensitive)
		}

		if negate {
			if matched {
				return false, 0
			}
		} else {
			if !matched {
				return false, 0
			}
			totalScore += score
		}
	}
	return true, totalScore
}
EOF
