{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"flag"
	"fmt"
	"os"
	"sort"
	"strings"
)

func main() {
	filterPtr := flag.String("f", "", "Filter mode")
	queryPtr := flag.String("q", "", "Initial query")
	exactPtr := flag.Bool("e", false, "Exact match")
	caseSensitivePtr := flag.Bool("i", false, "Case-insensitive match")
	noIgnoreCasePtr := flag.Bool("no-ignore-case", false, "Case-sensitive match")
	smartCasePtr := flag.Bool("smart-case", true, "Smart-case match")

	// Note: flag package doesn't handle +i or --no-extended easily.
	// For a real reimplementation, I should probably use a better flag parser or parse os.Args manually.
	flag.Parse()

	query := *filterPtr
	if query == "" && *queryPtr != "" {
		query = *queryPtr
	}

	caseSensitive := false
	if *noIgnoreCasePtr {
		caseSensitive = true
	} else if *caseSensitivePtr {
		caseSensitive = false
	} else if *smartCasePtr {
		caseSensitive = false
		for _, r := range query {
			if r >= 'A' && r <= 'Z' {
				caseSensitive = true
				break
			}
		}
	}

	if *filterPtr != "" || !isatty(os.Stdin) {
		// Filter mode or non-interactive
		runFilter(query, caseSensitive)
		return
	}

	// TUI mode would go here
	fmt.Fprintln(os.Stderr, "TUI mode not implemented yet")
}

func isatty(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func runFilter(query string, caseSensitive bool) {
	terms := strings.Split(query, " ")
	var matches []Match
	scanner := bufio.NewScanner(os.Stdin)
	index := 0
	for scanner.Scan() {
		text := scanner.Text()
		matched, score := ExtendedMatch(text, terms, caseSensitive)
		if matched {
			matches = append(matches, Match{Text: text, Score: score, Index: index})
		}
		index++
	}

	// Sort by score (descending), then by index (ascending)
	sort.Slice(matches, func(i, j int) bool {
		if matches[i].Score != matches[j].Score {
			return matches[i].Score > matches[j].Score
		}
		return matches[i].Index < matches[j].Index
	})

	for _, m := range matches {
		fmt.Println(m.Text)
	}
}
EOF
./compile.sh
echo -e "apple\nbanana\ncherry" | ./executable -f "a"
"}

