package main

import (
	"fmt"
	"os"
	"os/exec"
	"sort"
	"strings"
)

type TUI struct {
	query         string
	cursor        int
	items         []string
	matches       []Match
	height        int
	width         int
	tty           *os.File
	caseSensitive bool
}

func NewTUI(items []string, caseSensitive bool) *TUI {
	tty, _ := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	t := &TUI{
		items:         items,
		tty:           tty,
		caseSensitive: caseSensitive,
	}
	t.updateMatches()
	return t
}

func (t *TUI) updateMatches() {
	terms := strings.Split(t.query, " ")
	t.matches = nil
	for i, item := range t.items {
		matched, score := ExtendedMatch(item, terms, t.caseSensitive)
		if matched {
			t.matches = append(t.matches, Match{Text: item, Score: score, Index: i})
		}
	}
	sort.Slice(t.matches, func(i, j int) bool {
		if t.matches[i].Score != t.matches[j].Score {
			return t.matches[i].Score > t.matches[j].Score
		}
		return t.matches[i].Index < t.matches[j].Index
	})
	if t.cursor >= len(t.matches) {
		t.cursor = len(t.matches) - 1
	}
	if t.cursor < 0 && len(t.matches) > 0 {
		t.cursor = 0
	}
}

func (t *TUI) Run() string {
	// Set raw mode
	oldState, _ := exec.Command("stty", "-g").Output()
	exec.Command("stty", "-F", "/dev/tty", "raw", "-echo", "cbreak").Run()
	defer exec.Command("stty", "-F", "/dev/tty", string(oldState)).Run()

	// Hide cursor
	fmt.Fprint(t.tty, "\033[?25l")
	defer fmt.Fprint(t.tty, "\033[?25h")

	for {
		t.updateSize()
		t.render()

		var b [3]byte
		n, _ := t.tty.Read(b[:])
		if n == 0 {
			continue
		}

		if b[0] == 3 { // Ctrl-C
			return ""
		} else if b[0] == 13 { // Enter
			if t.cursor >= 0 && t.cursor < len(t.matches) {
				return t.matches[t.cursor].Text
			}
			return ""
		} else if b[0] == 27 { // Escape sequence
			if n > 1 && b[1] == 91 {
				if b[2] == 65 { // Up
					if t.cursor < len(t.matches)-1 {
						t.cursor++
					}
				} else if b[2] == 66 { // Down
					if t.cursor > 0 {
						t.cursor--
					}
				}
			} else if n == 1 {
				return "" // Esc
			}
		} else if b[0] == 127 { // Backspace
			if len(t.query) > 0 {
				t.query = t.query[:len(t.query)-1]
				t.updateMatches()
			}
		} else if b[0] >= 32 && b[0] <= 126 {
			t.query += string(b[0])
			t.updateMatches()
		}
	}
}

func (t *TUI) updateSize() {
	cmd := exec.Command("stty", "-F", "/dev/tty", "size")
	out, _ := cmd.Output()
	fmt.Sscanf(string(out), "%d %d", &t.height, &t.width)
}

func (t *TUI) render() {
	// Move to bottom left
	fmt.Fprintf(t.tty, "\033[%d;1H", t.height)
	// Clear lines from bottom up
	for i := 0; i < t.height; i++ {
		fmt.Fprintf(t.tty, "\033[%d;1H\033[2K", t.height-i)
	}

	// Render prompt
	fmt.Fprintf(t.tty, "\033[%d;1H> %s", t.height, t.query)

	// Render matches
	for i := 0; i < len(t.matches) && i < t.height-1; i++ {
		line := t.height - 1 - i
		prefix := "  "
		if i == t.cursor {
			prefix = "> "
		}
		text := t.matches[i].Text
		if len(text) > t.width-2 {
			text = text[:t.width-2]
		}
		fmt.Fprintf(t.tty, "\033[%d;1H%s%s", line, prefix, text)
	}
	// Move cursor to end of prompt
	fmt.Fprintf(t.tty, "\033[%d;%dH", t.height, len(t.query)+3)
	// Show cursor
	fmt.Fprint(t.tty, "\033[?25h")
}
