	"flag"
	"fmt"
	"os"
	"sort"
	"strings"
)

func main() {
	filterPtr := flag.String("f", "", "Filter mode")
	queryPtr := flag.String("q", "", "Initial query")
	caseSensitivePtr := flag.Bool("i", false, "Case-insensitive match")
	noIgnoreCasePtr := flag.Bool("no-ignore-case", false, "Case-sensitive match")
	smartCasePtr := flag.Bool("smart-case", true, "Smart-case match")
	layoutPtr := flag.String("layout", "default", "Layout: [default|reverse|reverse-list]")
	reversePtr := flag.Bool("reverse", false, "A synonym for --layout=reverse")

	flag.Parse()

	query := *filterPtr
	if query == "" && *queryPtr != "" {
		query = *queryPtr
	}

	caseSensitive := false
	if *noIgnoreCasePtr {
		caseSensitive = true
	} else if *caseSensitivePtr {
		caseSensitive = false
	} else if *smartCasePtr {
		caseSensitive = false
		for _, r := range query {
			if r >= 'A' && r <= 'Z' {
				caseSensitive = true
				break
			}
		}
	}

	isReverse := *reversePtr || *layoutPtr == "reverse"

	if *filterPtr != "" {
		runFilter(query, caseSensitive)
		return
	}

	var items []string
	if !isatty(os.Stdin) {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			items = append(items, scanner.Text())
		}
	} else {
		// If stdin is TTY, fzf should run a command.
		// For simplicity, let's just use "find ." or similar.
		cmdName := os.Getenv("FZF_DEFAULT_COMMAND")
		if cmdName == "" {
			cmdName = "find . -maxdepth 1"
		}
		parts := strings.Fields(cmdName)
		cmd := exec.Command(parts[0], parts[1:]...)
		out, err := cmd.Output()
		if err == nil {
			items = strings.Split(string(out), "\n")
		}
	}

	if len(items) == 0 {
		return
	}

	tui := NewTUI(items, caseSensitive, isReverse)
	selected := tui.Run()
	if selected != "" {
		fmt.Println(selected)
	}
}

func isatty(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func runFilter(query string, caseSensitive bool) {
	terms := strings.Split(query, " ")
	var matches []Match
	scanner := bufio.NewScanner(os.Stdin)
	index := 0
	for scanner.Scan() {
		text := scanner.Text()
		matched, score := ExtendedMatch(text, terms, caseSensitive)
		if matched {
			matches = append(matches, Match{Text: text, Score: score, Index: index})
		}
		index++
	}

	sort.Slice(matches, func(i, j int) bool {
		if matches[i].Score != matches[j].Score {
			return matches[i].Score > matches[j].Score
		}
		return matches[i].Index < matches[j].Index
	})

	for _, m := range matches {
		fmt.Println(m.Text)
	}
}
