	multi         bool
}

func NewTUI(items []string, caseSensitive bool, reverse bool, multi bool) *TUI {
	tty, _ := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	t := &TUI{
		items:         items,
		selected:      make(map[int]bool),
		tty:           tty,
		caseSensitive: caseSensitive,
		reverse:       reverse,
		multi:         multi,
	}
	t.updateMatches()
	return t
}

func (t *TUI) updateMatches() {
	terms := strings.Split(t.query, " ")
	t.matches = nil
	for i, item := range t.items {
		if item == "" && i == len(t.items)-1 { continue }
		matched, score := ExtendedMatch(item, terms, t.caseSensitive)
		if matched {
			t.matches = append(t.matches, Match{Text: item, Score: score, Index: i})
		}
	}
	sort.Slice(t.matches, func(i, j int) bool {
		if t.matches[i].Score != t.matches[j].Score {
			return t.matches[i].Score > t.matches[j].Score
		}
		return t.matches[i].Index < t.matches[j].Index
	})
	if t.cursor >= len(t.matches) {
		t.cursor = len(t.matches) - 1
	}
	if t.cursor < 0 && len(t.matches) > 0 {
		t.cursor = 0
	}
}

func (t *TUI) Run() []string {
	oldState, _ := exec.Command("stty", "-F", "/dev/tty", "-g").Output()
	exec.Command("stty", "-F", "/dev/tty", "raw", "-echo", "cbreak").Run()
	defer exec.Command("stty", "-F", "/dev/tty", string(oldState)).Run()

	fmt.Fprint(t.tty, "\033[?1049h")
	defer fmt.Fprint(t.tty, "\033[?1049l")

	for {
		t.updateSize()
		t.render()

		var b [3]byte
		n, _ := t.tty.Read(b[:])
		if n == 0 {
			continue
		}

		if b[0] == 3 { // Ctrl-C
			return nil
		} else if b[0] == 13 { // Enter
			var result []string
			if t.multi && len(t.selected) > 0 {
				// Return selected items in order of their appearance in input?
				// Actually fzf returns them in order they were selected or as they appear.
				// Let's return them as they appear in the original items list.
				for i, item := range t.items {
					if t.selected[i] {
						result = append(result, item)
					}
				}
			} else if t.cursor >= 0 && t.cursor < len(t.matches) {
				result = append(result, t.matches[t.cursor].Text)
			}
			return result
		} else if b[0] == 9 { // Tab
			if t.multi && t.cursor >= 0 && t.cursor < len(t.matches) {
				idx := t.matches[t.cursor].Index
				t.selected[idx] = !t.selected[idx]
				// Move cursor
				if t.reverse {
					if t.cursor < len(t.matches)-1 { t.cursor++ }
				} else {
					if t.cursor < len(t.matches)-1 { t.cursor++ } else if t.cursor > 0 { t.cursor-- }
				}
			}
		} else if b[0] == 27 {
			if n > 1 && b[1] == 91 {
				if b[2] == 65 { // Up
					if t.reverse {
						if t.cursor > 0 { t.cursor-- }
					} else {
						if t.cursor < len(t.matches)-1 { t.cursor++ }
					}
				} else if b[2] == 66 { // Down
					if t.reverse {
						if t.cursor < len(t.matches)-1 { t.cursor++ }
					} else {
						if t.cursor > 0 { t.cursor-- }
					}
				} else if b[2] == 90 { // Shift-Tab
					if t.multi && t.cursor >= 0 && t.cursor < len(t.matches) {
						idx := t.matches[t.cursor].Index
						t.selected[idx] = !t.selected[idx]
						// Move cursor in opposite direction
						if t.reverse {
							if t.cursor > 0 { t.cursor-- }
						} else {
							if t.cursor > 0 { t.cursor-- }
						}
					}
				}
			} else if n == 1 {
				return nil
			}
		} else if b[0] == 127 { // Backspace
			if len(t.query) > 0 {
				t.query = t.query[:len(t.query)-1]
				t.updateMatches()
			}
		} else if b[0] >= 32 && b[0] <= 126 {
			t.query += string(b[0])
			t.updateMatches()
		} else if b[0] == 14 { // Ctrl-N
			if t.reverse {
				if t.cursor < len(t.matches)-1 { t.cursor++ }
			} else {
				if t.cursor > 0 { t.cursor-- }
			}
		} else if b[0] == 16 { // Ctrl-P
			if t.reverse {
				if t.cursor > 0 { t.cursor-- }
			} else {
				if t.cursor < len(t.matches)-1 { t.cursor++ }
			}
		}
	}
