package main

import (
	"strings"
	"unicode"
)

type Match struct {
	Text  string
	Score int
	Index int
}

func isBoundary(r rune) bool {
	return r == 0 || !unicode.IsLetter(r) && !unicode.IsNumber(r)
}

func FuzzyMatch(text, query string, caseSensitive bool) (bool, int) {
	tText := text
	tQuery := query
	if !caseSensitive {
		tText = strings.ToLower(text)
		tQuery = strings.ToLower(query)
	}

	if len(tQuery) == 0 {
		return true, 0
	}

	resScore := 0
	queryIdx := 0

	lastMatchIdx := -1

	for i := 0; i < len(tText); i++ {
		if queryIdx < len(tQuery) && tText[i] == tQuery[queryIdx] {
			score := 10

			// Bonus for consecutive matches
			if lastMatchIdx == i-1 {
				score += 20
			}

			// Bonus for boundary matches
			var prev rune
			if i > 0 {
				prev = rune(tText[i-1])
			}
			if isBoundary(prev) {
				score += 30
			}

			// Bonus for path separator
			if prev == '/' || prev == '\\' {
				score += 40
			}

			resScore += score
			lastMatchIdx = i
			queryIdx++
		}
	}

	if queryIdx == len(tQuery) {
		// Penalty for length
		resScore -= len(text)
		return true, resScore
	}

	return false, 0
}

func ExtendedMatch(text string, terms []string, caseSensitive bool) (bool, int) {
	totalScore := 0
	for _, term := range terms {
		if len(term) == 0 {
			continue
		}

		negate := false
		if strings.HasPrefix(term, "!") {
			negate = true
			term = term[1:]
		}

		if len(term) == 0 {
			continue
		}

		matched := false
		score := 0

		if strings.HasPrefix(term, "'") {
			exact := term[1:]
			if caseSensitive {
				matched = strings.Contains(text, exact)
			} else {
				matched = strings.Contains(strings.ToLower(text), strings.ToLower(exact))
			}
			score = 100
		} else if strings.HasPrefix(term, "^") {
			prefix := term[1:]
			if caseSensitive {
				matched = strings.HasPrefix(text, prefix)
			} else {
				matched = strings.HasPrefix(strings.ToLower(text), strings.ToLower(prefix))
			}
			score = 100
		} else if strings.HasSuffix(term, "$") {
			suffix := term[:len(term)-1]
			if caseSensitive {
				matched = strings.HasSuffix(text, suffix)
			} else {
				matched = strings.HasSuffix(strings.ToLower(text), strings.ToLower(suffix))
			}
			score = 100
		} else {
			matched, score = FuzzyMatch(text, term, caseSensitive)
		}

		if negate {
			if matched {
				return false, 0
			}
		} else {
			if !matched {
				return false, 0
			}
			totalScore += score
		}
	}
	return true, totalScore
}
